/**
 * PNG color profile and validation for the browser-only print pipeline.
 *
 * The image is decoded and painted onto an explicit sRGB Canvas2D context.
 * A generated, standards-compliant LittleCMS sRGB display profile is embedded
 * through PNG iCCP when requested. Never just retag raw wide-gamut bytes.
 */

// sRGB ICC v4 profile generated by LittleCMS ImageCms.createProfile('sRGB').
// RGB display, XYZ PCS; 588 bytes. This is a real ICC payload, not a PNG sRGB flag.
const SRGB_ICC_BASE64 = ''
const SIGNATURE = [137, 80, 78, 71, 13, 10, 26, 10]
const encoder = new TextEncoder()
const crcTable = new Uint32Array(256)
for (let i = 0; i < 256; i++) {
  let crc = i
  for (let j = 0; j < 8; j++) crc = crc & 1 ? (crc >>> 1) ^ 0xedb88320 : crc >>> 1
  crcTable[i] = crc >>> 0
}
function crc32(bytes: Uint8Array) {
  let c = 0xffffffff
  for (const byte of bytes) c = crcTable[(c ^ byte) & 255] ^ (c >>> 8)
  return (c ^ 0xffffffff) >>> 0
}
function adler32(bytes: Uint8Array) {
  let a = 1
  let b = 0
  for (const value of bytes) { a = (a + value) % 65521; b = (b + a) % 65521 }
  return ((b << 16) | a) >>> 0
}
function deflateStored(bytes: Uint8Array) {
  // Correct zlib stream, using uncompressed DEFLATE blocks. Profiles are small;
  // STORE is cross-browser and needs no dependency or CompressionStream API.
  const parts: number[] = [0x78, 0x01]
  let offset = 0
  do {
    const length = Math.min(65535, bytes.length - offset)
    const last = offset + length === bytes.length
    parts.push(last ? 1 : 0, length & 255, length >>> 8, (~length) & 255, (~length >>> 8) & 255)
    for (let i = 0; i < length; i++) parts.push(bytes[offset + i])
    offset += length
  } while (offset < bytes.length)
  const checksum = adler32(bytes)
  parts.push(checksum >>> 24, (checksum >>> 16) & 255, (checksum >>> 8) & 255, checksum & 255)
  return new Uint8Array(parts)
}
function makeChunk(type: string, payload: Uint8Array) {
  const name = encoder.encode(type)
  const result = new Uint8Array(12 + payload.byteLength)
  const view = new DataView(result.buffer)
  view.setUint32(0, payload.byteLength, false)
  result.set(name, 4)
  result.set(payload, 8)
  view.setUint32(result.length - 4, crc32(result.subarray(4, result.length - 4)), false)
  return result
}

async function readSignature(blob: Blob) {
  const bytes = new Uint8Array(await blob.slice(0, 8).arrayBuffer())
  if (bytes.length !== 8 || bytes.some((b, i) => b !== SIGNATURE[i])) throw new Error('La salida no es un PNG válido.')
}
async function readChunkHeader(blob: Blob, offset: number) {
  if (offset + 12 > blob.size) throw new Error('PNG incompleto.')
  const bytes = new Uint8Array(await blob.slice(offset, offset + 8).arrayBuffer())
  const size = new DataView(bytes.buffer).getUint32(0, false)
  const type = String.fromCharCode(bytes[4], bytes[5], bytes[6], bytes[7])
  if (offset + size + 12 > blob.size) throw new Error('PNG truncado.')
  return { size, type, end: offset + size + 12 }
}

export async function embedSrgbIcc(blob: Blob) {
  await readSignature(blob)
  const raw = atob(SRGB_ICC_BASE64)
  const icc = Uint8Array.from(raw, (c) => c.charCodeAt(0))
  const name = encoder.encode('sRGB built-in')
  const payload = new Uint8Array(name.length + 2 + deflateStored(icc).length)
  payload.set(name, 0)
  const compressed = deflateStored(icc)
  payload.set(compressed, name.length + 2) // NUL + compression method=0
  const chunk = makeChunk('iCCP', payload)

  const parts: BlobPart[] = [blob.slice(0, 8)]
  let offset = 8
  let wrote = false
  while (offset + 12 <= blob.size) {
    const { type, end } = await readChunkHeader(blob, offset)
    if (type === 'IDAT') {
      if (!wrote) throw new Error('Falta IHDR en PNG.')
      parts.push(blob.slice(offset))
      break
    }
    // iCCP and sRGB cannot coexist. gAMA/cHRM from an old profile must not
    // contradict the embedded ICC. Preserve pHYs and other unrelated chunks.
    if (!['iCCP', 'sRGB', 'gAMA', 'cHRM'].includes(type)) parts.push(blob.slice(offset, end))
    if (type === 'IHDR') { parts.push(chunk); wrote = true }
    offset = end
  }
  if (!wrote) throw new Error('No se pudo incrustar el perfil ICC.')
  return new Blob(parts, { type: 'image/png' })
}

export type PngInspection = {
  width: number
  height: number
  bitDepth: number
  colorType: number
  icc: boolean
  dpi: number | null
}
export async function inspectPng(blob: Blob): Promise<PngInspection> {
  await readSignature(blob)
  let offset = 8
  let output: PngInspection | null = null
  while (offset + 12 <= blob.size) {
    const { size, type, end } = await readChunkHeader(blob, offset)
    if (type === 'IHDR') {
      if (size !== 13) throw new Error('Cabecera PNG inválida.')
      const raw = await blob.slice(offset + 8, offset + 8 + size).arrayBuffer()
      const view = new DataView(raw)
      output = { width: view.getUint32(0, false), height: view.getUint32(4, false),
        bitDepth: view.getUint8(8), colorType: view.getUint8(9), icc: false, dpi: null }
    }
    if (type === 'iCCP' && output) output.icc = true
    if (type === 'pHYs' && output && size === 9) {
      const bytes = new DataView(await blob.slice(offset + 8, offset + 17).arrayBuffer())
      if (bytes.getUint8(8) === 1) output.dpi = Math.round(bytes.getUint32(0, false) * 0.0254)
    }
    if (type === 'IDAT') break
    offset = end
  }
  if (!output) throw new Error('PNG sin cabecera.')
  return output
}

/** Never claim a PNG is 8-bit RGBA if the browser emitted another color type. */
export async function verifyPrintPng(blob: Blob, expected: { width: number; height: number; dpi: number | null; icc: boolean }) {
  const actual = await inspectPng(blob)
  if (actual.width !== expected.width || actual.height !== expected.height) throw new Error('El PNG no conserva las dimensiones solicitadas.')
  if (actual.bitDepth !== 8 || actual.colorType !== 6) throw new Error('No se pudo garantizar PNG RGBA de 8 bits por canal.')
  if (expected.dpi !== null && actual.dpi !== expected.dpi) throw new Error('El PNG no incluye correctamente los 300 ppp.')
  if (expected.icc && !actual.icc) throw new Error('Falta el perfil ICC sRGB.')
  return actual
}
